BEGIN;
GRANT USAGE ON SCHEMA public,auth TO authenticated;
GRANT ALL ON ALL TABLES IN SCHEMA public TO authenticated;
-- Deliberately broad legacy grants must not allow bypassing the new commands.
REVOKE ALL ON invoice_review_drafts FROM authenticated;
CREATE FUNCTION review_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'FAIL: %',label;END IF;RAISE NOTICE 'PASS: %',label;END; $$;
CREATE FUNCTION review_reject(command text,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE command; EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'PASS rejected: % [%]',label,SQLERRM;RETURN;END;RAISE EXCEPTION 'FAIL accepted: %',label;END; $$;
CREATE FUNCTION review_token(f uuid) RETURNS text LANGUAGE sql AS $$ SELECT value->>'reviewToken' FROM jsonb_array_elements(get_invoice_review_context('e3000000-0000-4000-8000-000000000001')->'invoices') WHERE value->>'factureId'=f::text $$;
CREATE FUNCTION review_lines(price numeric DEFAULT 100) RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_build_array(jsonb_build_object('desc','Article vérifié','qte',1,'prix',price,'cat','e4000000-0000-4000-8000-000000000001')) $$;
INSERT INTO auth.users(id,email) VALUES('e1000000-0000-4000-8000-000000000001','review-director@example.test'),('e1000000-0000-4000-8000-000000000002','review-client@example.test'),('e1000000-0000-4000-8000-000000000003','review-preparer@example.test');
INSERT INTO staff_users(id,auth_id,nom,email,role,must_change_password) VALUES('e1100000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','Review director','review-director@example.test','directeur',false),('e1100000-0000-4000-8000-000000000003','e1000000-0000-4000-8000-000000000003','Review preparer','review-preparer@example.test','preparateur',false);
INSERT INTO staff_permissions(staff_id,perm_factures_voir,perm_factures_modifier_articles,perm_factures_valider) VALUES('e1100000-0000-4000-8000-000000000003',true,true,false);
INSERT INTO clients(id,user_id,nom,cp,type) VALUES('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000002','Review','97400','particulier');
INSERT INTO colis(id,client_id,statut,nb_colis,dims_par_colis,feu_vert) VALUES('e3000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','en_preparation',1,'[{"dimL":40,"dimW":30,"dimH":20,"poids":3}]','autorise');
INSERT INTO categories(id,label) VALUES('e4000000-0000-4000-8000-000000000001','Review category');
INSERT INTO taux_categories(categorie_id,destination_code,om,omr) VALUES('e4000000-0000-4000-8000-000000000001','974',10,2.5);
UPDATE tarifs SET base=10,par_kg=5 WHERE destination_code='974';UPDATE destinations SET tva=8.5 WHERE code='974';
INSERT INTO factures(id,colis_id,vendeur,montant,fichier_url) VALUES
('e5000000-0000-4000-8000-000000000001','e3000000-0000-4000-8000-000000000001','Original',0,'e3000000-0000-4000-8000-000000000001/original.pdf'),
('e5000000-0000-4000-8000-000000000002','e3000000-0000-4000-8000-000000000001','Copy',0,'e3000000-0000-4000-8000-000000000001/copy.pdf');
INSERT INTO storage.objects(bucket_id,name) SELECT 'factures',fichier_url FROM factures WHERE colis_id='e3000000-0000-4000-8000-000000000001';
INSERT INTO ocr_extractions(id,facture_id,document_hash,document_file_url,lines,total) SELECT CASE WHEN id='e5000000-0000-4000-8000-000000000001' THEN 'e6000000-0000-4000-8000-000000000001'::uuid ELSE 'e6000000-0000-4000-8000-000000000002'::uuid END,id,'exact-sha256',fichier_url,review_lines(),100 FROM factures WHERE colis_id='e3000000-0000-4000-8000-000000000001';
INSERT INTO lignes(colis_id,description,qte,prix_unitaire,categorie_id) VALUES('e3000000-0000-4000-8000-000000000001','Independent manual article',1,0,'e4000000-0000-4000-8000-000000000001');
SELECT review_assert(NOT has_function_privilege('anon','save_invoice_review(uuid,text,text,jsonb,numeric,text,uuid,boolean)','EXECUTE'),'anonymous cannot review');
SELECT review_assert(NOT has_function_privilege('authenticated','invoice_storage_identity(text)','EXECUTE'),'browser cannot forge storage proof');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',true),set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000002',true);
SELECT review_reject($q$SELECT get_invoice_review_context('e3000000-0000-4000-8000-000000000001')$q$,'customer cannot read staff review drafts');
SELECT set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000003',true);
SELECT review_reject($q$SELECT save_invoice_review('e5000000-0000-4000-8000-000000000001',review_token('e5000000-0000-4000-8000-000000000001'),'e3000000-0000-4000-8000-000000000001/original.pdf',review_lines(),100,'Vendor',NULL,NULL)$q$,'null confirm cannot bypass validation permission');
SELECT save_invoice_review('e5000000-0000-4000-8000-000000000001',review_token('e5000000-0000-4000-8000-000000000001'),'e3000000-0000-4000-8000-000000000001/original.pdf','[{"desc":"À compléter","qte":1,"prix":null,"cat":null}]',NULL,'Vendor',NULL,false);
SELECT review_assert((SELECT NOT valide FROM factures WHERE id='e5000000-0000-4000-8000-000000000001') AND NOT EXISTS(SELECT 1 FROM lignes WHERE facture_id='e5000000-0000-4000-8000-000000000001'),'draft preserves incomplete fields without altering invoice/articles');
SELECT review_assert(get_invoice_review_context('e3000000-0000-4000-8000-000000000001')->'invoices'->0->'draft'->'lines'->0->>'desc'='À compléter','saved draft is restored in context');
SELECT set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000001',true);
SELECT review_assert(jsonb_array_length(get_invoice_review_context('e3000000-0000-4000-8000-000000000001')->'invoices')=2,'context exposes all invoices and their analyses');
SELECT review_assert(jsonb_array_length(get_invoice_review_context('e3000000-0000-4000-8000-000000000001')->'invoices'->0->'duplicateCandidateIds')=1,'exact-hash candidate is visible without downloading PDFs');
SELECT review_reject($q$UPDATE factures SET duplicate_of_facture_id='e5000000-0000-4000-8000-000000000001' WHERE id='e5000000-0000-4000-8000-000000000002'$q$,'direct duplicate classification is forbidden even with legacy broad grants');
SELECT review_reject($q$SELECT save_invoice_review('e5000000-0000-4000-8000-000000000001','stale','e3000000-0000-4000-8000-000000000001/original.pdf',review_lines(),100,'Vendor')$q$,'stale review token cannot overwrite colleague changes');
SELECT review_reject($q$SELECT save_invoice_review('e5000000-0000-4000-8000-000000000001',review_token('e5000000-0000-4000-8000-000000000001'),'changed.pdf',review_lines(),100,'Vendor')$q$,'changed file rejected');
SELECT review_reject($q$SELECT save_invoice_review('e5000000-0000-4000-8000-000000000001',review_token('e5000000-0000-4000-8000-000000000001'),'e3000000-0000-4000-8000-000000000001/original.pdf',review_lines(),101,'Vendor')$q$,'mismatched article total rejected atomically');
SELECT review_reject($q$SELECT save_invoice_review('e5000000-0000-4000-8000-000000000001',review_token('e5000000-0000-4000-8000-000000000001'),'e3000000-0000-4000-8000-000000000001/original.pdf','[{"desc":"Article","qte":1,"prix":100,"cat":null}]',100,'Vendor')$q$,'uncategorized invoice cannot be approved');
SELECT review_reject($q$SELECT save_invoice_review('e5000000-0000-4000-8000-000000000001',review_token('e5000000-0000-4000-8000-000000000001'),'e3000000-0000-4000-8000-000000000001/original.pdf',review_lines(),100,'Vendor','e6000000-0000-4000-8000-000000000001')$q$,'historical extraction requires current verified object proof');
SELECT review_reject($q$SELECT classify_invoice_duplicate('e5000000-0000-4000-8000-000000000002','e5000000-0000-4000-8000-000000000001',review_token('e5000000-0000-4000-8000-000000000002'),review_token('e5000000-0000-4000-8000-000000000001'))$q$,'historical equal hashes alone cannot classify a copy');
SELECT review_token('e5000000-0000-4000-8000-000000000001') AS storage_old_token \gset
RESET ROLE;
UPDATE ocr_extractions SET document_storage_identity=invoice_storage_identity(document_file_url) WHERE id='e6000000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT review_assert(review_token('e5000000-0000-4000-8000-000000000001')=:'storage_old_token','verified technical binding alone does not invalidate the operator draft');
RESET ROLE;
UPDATE storage.objects SET id=gen_random_uuid() WHERE name='e3000000-0000-4000-8000-000000000001/original.pdf';
SET LOCAL ROLE authenticated;
SELECT review_reject(format('SELECT save_invoice_review(%L,%L,%L,review_lines(),100,%L)','e5000000-0000-4000-8000-000000000001',:'storage_old_token','e3000000-0000-4000-8000-000000000001/original.pdf','Vendor'),'replacement at the same storage path invalidates the review token');
SELECT review_assert((SELECT value->'extraction'='null'::jsonb AND value->'documentHash'='null'::jsonb AND jsonb_array_length(value->'duplicateCandidateIds')=0 FROM jsonb_array_elements(get_invoice_review_context('e3000000-0000-4000-8000-000000000001')->'invoices') WHERE value->>'factureId'='e5000000-0000-4000-8000-000000000001'),'same-path replacement hides the stale analysis, hash and duplicate suggestions');
SELECT review_assert((SELECT value->'extraction'->>'id'='e6000000-0000-4000-8000-000000000002' AND jsonb_array_length(value->'duplicateCandidateIds')=0 FROM jsonb_array_elements(get_invoice_review_context('e3000000-0000-4000-8000-000000000001')->'invoices') WHERE value->>'factureId'='e5000000-0000-4000-8000-000000000002'),'legacy unbound analysis remains visible but never suggests a counterpart with stale proof');
RESET ROLE;
UPDATE ocr_extractions SET document_storage_identity=invoice_storage_identity(document_file_url) WHERE facture_id IN ('e5000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000002');
SET LOCAL ROLE authenticated;
SELECT review_token('e5000000-0000-4000-8000-000000000001') AS prior_token \gset
SELECT save_invoice_review('e5000000-0000-4000-8000-000000000001',:'prior_token','e3000000-0000-4000-8000-000000000001/original.pdf',review_lines(),100,'Vendor','e6000000-0000-4000-8000-000000000001');
SELECT review_assert((SELECT valide AND montant=100 FROM factures WHERE id='e5000000-0000-4000-8000-000000000001') AND (SELECT count(*)=1 FROM lignes WHERE facture_id='e5000000-0000-4000-8000-000000000001'),'single action confirms invoice and creates articles');
SELECT review_reject(format('SELECT save_invoice_review(%L,%L,%L,review_lines(),100,%L)','e5000000-0000-4000-8000-000000000001',:'prior_token','e3000000-0000-4000-8000-000000000001/original.pdf','Vendor'),'replaying a lost response cannot duplicate articles');
SELECT review_assert((SELECT count(*)=1 FROM lignes WHERE facture_id='e5000000-0000-4000-8000-000000000001') AND (SELECT count(*)=1 FROM lignes WHERE colis_id='e3000000-0000-4000-8000-000000000001' AND facture_id IS NULL),'retry leaves one article and preserves independent manual article');
SELECT review_assert((SELECT count(*)=1 FROM audit_actions WHERE action='invoice_review_confirmed' AND before_data IS NOT NULL AND after_data IS NOT NULL),'confirmation preserves before/after journal');
SELECT save_invoice_review('e5000000-0000-4000-8000-000000000002',review_token('e5000000-0000-4000-8000-000000000002'),'e3000000-0000-4000-8000-000000000001/copy.pdf',review_lines(),100,'Vendor',NULL);
RESET ROLE;
UPDATE ocr_extractions SET document_hash='different-sha256' WHERE id='e6000000-0000-4000-8000-000000000002';
SET LOCAL ROLE authenticated;
SELECT review_reject($q$SELECT classify_invoice_duplicate('e5000000-0000-4000-8000-000000000002','e5000000-0000-4000-8000-000000000001',review_token('e5000000-0000-4000-8000-000000000002'),review_token('e5000000-0000-4000-8000-000000000001'))$q$,'different verified files can never be classified as exact copies');
RESET ROLE;
UPDATE ocr_extractions SET document_hash='exact-sha256' WHERE id='e6000000-0000-4000-8000-000000000002';
SET LOCAL ROLE authenticated;
SELECT classify_invoice_duplicate('e5000000-0000-4000-8000-000000000002','e5000000-0000-4000-8000-000000000001',review_token('e5000000-0000-4000-8000-000000000002'),review_token('e5000000-0000-4000-8000-000000000001'));
SELECT review_assert((SELECT duplicate_of_facture_id='e5000000-0000-4000-8000-000000000001' AND rejet_motif IS NULL FROM factures WHERE id='e5000000-0000-4000-8000-000000000002') AND (SELECT count(*)=1 FROM lignes WHERE facture_id='e5000000-0000-4000-8000-000000000002'),'explicit copy classification preserves invoice and article history, never invents rejection');
SELECT review_reject($q$DELETE FROM factures WHERE id='e5000000-0000-4000-8000-000000000002'$q$,'copy deletion cannot detach its articles back into the quote');
SELECT review_reject($q$DELETE FROM lignes WHERE facture_id='e5000000-0000-4000-8000-000000000002'$q$,'excluded copy articles cannot be silently changed');
SELECT review_reject($q$UPDATE factures SET fichier_url='replacement.pdf' WHERE id='e5000000-0000-4000-8000-000000000001'$q$,'canonical document cannot change while its classified copies refer to it');
SELECT save_preparation_measurements(id,'[{"dimL":40,"dimW":10,"dimH":10,"poids":2}]',updated_at,preparation_composition_version) FROM colis WHERE id='e3000000-0000-4000-8000-000000000001';
SELECT save_quote(id,'{"devisTransport":20,"devisOM":12,"devisOMR":3,"devisTVA":2.98,"devisTotal":37.98}',updated_at) FROM colis WHERE id='e3000000-0000-4000-8000-000000000001';
SELECT review_assert((SELECT devis_total=37.98 AND (devis_snapshot->'amounts'->>'merchandiseValue')::numeric=100 FROM colis WHERE id='e3000000-0000-4000-8000-000000000001'),'real quote excludes all duplicate-linked merchandise');
SELECT review_assert((SELECT state='done' FROM staff_work_actions WHERE colis_id='e3000000-0000-4000-8000-000000000001' AND kind='documents'),'excluded copy no longer blocks document work');
SELECT restore_invoice_duplicate('e5000000-0000-4000-8000-000000000002',review_token('e5000000-0000-4000-8000-000000000002'));
SELECT review_assert((SELECT duplicate_of_facture_id IS NULL AND NOT valide FROM factures WHERE id='e5000000-0000-4000-8000-000000000002') AND (SELECT devis_total IS NULL FROM colis WHERE id='e3000000-0000-4000-8000-000000000001'),'restore invalidates quote and requires fresh review');
SELECT review_reject($q$SELECT save_quote(id,'{}',updated_at) FROM colis WHERE id='e3000000-0000-4000-8000-000000000001'$q$,'restored unreviewed invoice blocks quote');
RESET ROLE;
UPDATE factures SET rejet_motif='Document corrigé demandé' WHERE id='e5000000-0000-4000-8000-000000000002';
INSERT INTO factures(id,colis_id,vendeur,montant,fichier_url,valide,replaces_facture_id) VALUES('e5000000-0000-4000-8000-000000000003','e3000000-0000-4000-8000-000000000001','Corrected vendor',100,'e3000000-0000-4000-8000-000000000001/corrected.pdf',true,'e5000000-0000-4000-8000-000000000002');
INSERT INTO lignes(colis_id,facture_id,description,qte,prix_unitaire,categorie_id) VALUES('e3000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000003','Corrected article',1,100,'e4000000-0000-4000-8000-000000000001');
-- Even a historical direct rejection reset cannot reactivate the superseded file.
UPDATE factures SET rejet_motif=NULL WHERE id='e5000000-0000-4000-8000-000000000002';
SET LOCAL ROLE authenticated;
SELECT review_reject($q$SELECT save_invoice_review('e5000000-0000-4000-8000-000000000002',review_token('e5000000-0000-4000-8000-000000000002'),'e3000000-0000-4000-8000-000000000001/copy.pdf',review_lines(),100,'Vendor')$q$,'replaced historical invoice cannot be revalidated');
SELECT save_quote(id,'{"devisTransport":20,"devisOM":22,"devisOMR":5.5,"devisTVA":4.04,"devisTotal":51.54}',updated_at) FROM colis WHERE id='e3000000-0000-4000-8000-000000000001';
SELECT review_assert((SELECT (devis_snapshot->'amounts'->>'merchandiseValue')::numeric=200 FROM colis WHERE id='e3000000-0000-4000-8000-000000000001'),'replaced invoice stays excluded even if legacy rejection is cleared');
SELECT review_assert((SELECT state='done' FROM staff_work_actions WHERE colis_id='e3000000-0000-4000-8000-000000000001' AND kind='documents'),'replaced unvalidated invoice does not block staff work');
RESET ROLE;
UPDATE colis SET paiement_date=now(),paiement_montant=51.54 WHERE id='e3000000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT review_reject($q$SELECT save_invoice_review('e5000000-0000-4000-8000-000000000002',review_token('e5000000-0000-4000-8000-000000000002'),'e3000000-0000-4000-8000-000000000001/copy.pdf',review_lines(),100,'Vendor')$q$,'paid dossier cannot be edited through review');
SELECT review_reject($q$SELECT classify_invoice_duplicate('e5000000-0000-4000-8000-000000000002','e5000000-0000-4000-8000-000000000001',review_token('e5000000-0000-4000-8000-000000000002'),review_token('e5000000-0000-4000-8000-000000000001'))$q$,'paid dossier cannot exclude documents');
ROLLBACK;
